import { StoryViewer, Button } from "march/ui"

// günün renkleri: dört renk, her biri iki saniyelik bir hikâye; sonuncusu bitince görüntüleyici kendiliğinden kapanır
const PNG = (p: string) => `data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42m${p}AAAAABJRU5ErkJggg==`
const DAY = [{
  id: "day", name: "Renk günlüğü", items: [
    { id: "dawn", src: PNG("P4+6zr9yQbhuXdvwz1GgE6ZgdD1tcTig"), caption: "06:40 · şafak pembesi" },
    { id: "sea", src: PNG("Ow2PuDb+lLBlm/Gz+LxQAthgZP+C/Xcg"), caption: "12:15 · öğle mavisi" },
    { id: "sunset", src: PNG("P4WSz2xmMmQ43VWzlpbwAsKgV3rhVt4w"), caption: "18:50 · gün batımı" },
    { id: "city", src: PNG("OQk/Y21GtkeLWZg19cCwAXQQNaq9+sQQ"), caption: "23:30 · şehir gecesi" },
  ],
}]

export function ColorDiary() {
  let $open = false
  return <div sx={{ flex: ["row", "center"], gap: 2 }}>
    <Button variant="primary" m:color="brand-pink" on:click={() => $open = true}>🎨 Günün renklerini aç</Button>
    <StoryViewer open={$open} onClose={() => $open = false} groups={DAY} duration={2000} arrows={false} avatar={false} time={false} />
