}

import { StoryViewer, StoryRing, toast, type StoryGroup } from "march/ui"

// bir uygulamanın hikâye şeridi: halkaya basınca o kişiden açılır; izlenen halkalar griye döner, beğeni ve yanıt
// gönderilebilir
const PNG = (p: string) => `data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42m${p}AAAAABJRU5ErkJggg==`
const ago = (m: number) => new Date(Date.now() - m * 60_000)
const GROUPS: StoryGroup[] = [
  { id: "run", name: "HADİ Koşu Kulübü", items: [
    { id: "run-1", src: PNG("P4+6zr9yQbhuXdvwz1GgE6ZgdD1tcTig"), caption: "Sabah koşusu başladı!", time: ago(20) },
    { id: "run-2", src: PNG("Ow2PuDb+lLBlm/Gz+LxQAthgZP+C/Xcg"), caption: "Sahil 5 km ✅", time: ago(12) },
  ] },
  { id: "bike", name: "Pazar Bisiklet", items: [{ id: "bike-1", src: PNG("PY/f2C0tE4BrFUE5FgXQAtngULJa1nqA"), caption: "Orman yolu", time: ago(75) }] },
  { id: "book", name: "Kitap Kulübü", items: [{ id: "book-1", src: PNG("P4+6xrSzAnQ4Up/7/PxwExlAbyzjJBwg"), caption: "Kahve ve kitap ☕", time: ago(140) }] },
]

export function StoryTray() {
  let $open = false
  let $who = "run"
  let $seen = new Set<string>()
  let $liked = new Set<string>()
  const allSeen = (g: StoryGroup) => g.items.every((s) => $seen.has(s.id))
  return <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
    {GROUPS.map((g) => <StoryRing name={g.name} state={allSeen(g) ? "seen" : "new"} onClick={() => { $who = g.id; $open = true }} />)}
    <StoryViewer open={$open} onClose={() => $open = false} groups={GROUPS} start={$who}
      onSeen={(_, s) => { if (!$seen.has(s.id)) $seen = new Set([...$seen, s.id]) }}
      liked={(_, s) => $liked.has(s.id)}
      onLike={(_, s, on) => { const n = new Set($liked); on ? n.add(s.id) : n.delete(s.id); $liked = n }}
      onReply={(g, _, text) => toast(`${g.name}: “${text}” gönderildi`)} />
  </div>
}

import { StoryViewer, Button, Badge, type StoryGroup } from "march/ui"

// StoryViewer'ın bütün özellikleri: açık / kapalı, gruplar (kendi süresi olan hikâye), başlangıç grubu, varsayılan süre,
// görüldü / yanıt / beğeni olayları ve beğeni durumu, ilerleme çubukları, avatar, zaman, duraklat, kapat, oklar,
// "gönderildi" notu, kendi metinler (ekran okuyucu durumu dahil) ve sınıf
const PNG = (p: string) => `data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR42m${p}AAAAABJRU5ErkJggg==`
const GROUPS: StoryGroup[] = [
  { id: "ece", name: "Ece", items: [
    { id: "e1", src: PNG("P4WSz2xmMmQ43VWzlpbwAsKgV3rhVt4w"), alt: "Gün batımı", caption: "Tepede gün batımı", time: new Date(Date.now() - 30 * 60_000) },
    { id: "e2", src: PNG("Ow2PuDb+lLBlm/Gz+LxQAthgZP+C/Xcg"), alt: "Deniz", duration: 9000 },
  ] },
  { id: "can", name: "Can", items: [{ id: "c1", src: PNG("OQk/Y21GtkeLWZg19cCwAXQQNaq9+sQQ"), alt: "Şehir", caption: "Gece turu" }] },
]

export function StoryViewerLab() {
  let $open = false
  let $start: string | number = 0
  let $seen: string[] = []
  let $liked = new Set<string>()
  let $log = "-"
  const show = (start: string | number) => { $start = start; $open = true }
  return <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
    <Button size="sm" on:click={() => show(0)}>Baştan aç</Button>
    <Button size="sm" variant="ghost" on:click={() => show("can")}>Can'dan aç</Button>
    <Badge tone="primary">{$log}</Badge>
    <span sx={{ text: "xs", color: "muted" }}>{`görülen: ${$seen.join(", ") || "-"}`}</span>
    <StoryViewer class="lab-stories" open={() => $open} onClose={() => { $open = false; $log = "kapandı" }}
      groups={GROUPS} start={() => $start} duration={4000}
      onSeen={(_, s) => { if (!$seen.includes(s.id)) $seen = [...$seen, s.id] }}
      onReply={(g, _, text) => $log = `${g.name}: ${text}`}
      onLike={(_, s, on) => { const n = new Set($liked); on ? n.add(s.id) : n.delete(s.id); $liked = n; $log = on ? "beğenildi" : "beğeni geri alındı" }}
      liked={(_, s) => $liked.has(s.id)}
      progress avatar time pauseButton closeButton arrows sentNote
      labels={{ dialog: "Hikâyeler", play: "Oynat", pause: "Durdur", close: "Hikâyeyi kapat", previous: "Önceki hikâye", next: "Sonraki hikâye",
        like: "Hikâyeyi beğen", send: "Yolla", sent: "İletildi ✓",
        reply: (g) => `${g.name} kişisine yanıt`, replyPlaceholder: (g) => `${g.name} için bir şey yaz…`,
        status: (g, i, n) => `${g.name}: ${i + 1}. hikâye / ${n}` }} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { StoryViewerLab } from "./StoryViewerLab.tsx"

// StoryViewerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Baştan aç ilk kişinin ilk hikâyesini gösterir ve görüldü olarak işaretler", async () => {
  const s = renderTest(() => <StoryViewerLab />)
  await s.click("Baştan aç")
  expect(s.sees("Tepede gün batımı")).toBe(true)
  await s.wait(() => s.sees("görülen: e1"))
  expect(s.sees("görülen: e1")).toBe(true)
})

test("start bir id de olabilir: Can'dan açar", async () => {
  const s = renderTest(() => <StoryViewerLab />)
  await s.click("Can'dan aç")
  expect(s.sees("Gece turu")).toBe(true)
})

test("kendi metinli kalp onLike'ı çalıştırır", async () => {
  const s = renderTest(() => <StoryViewerLab />)
  await s.click("Baştan aç")
  await s.click("Hikâyeyi beğen")
  expect(s.sees("beğenildi")).toBe(true)
})

test("kapat düğmesi onClose'u çalıştırır", async () => {
  const s = renderTest(() => <StoryViewerLab />)
  await s.click("Baştan aç")
  await s.click("Hikâyeyi kapat")
  await s.wait(() => s.sees("kapandı"))
  expect(s.sees("kapandı")).toBe(true)
})
